import { mountBalanceDemonstration } from './balance-demo.js';
import { prepareStudio } from './studio.js';
import { elements, molecules, molecularMass, parseFormula, format, formulaHTML, reactions, atomLedger, equationHTML, convert, react, finite } from './core.js';
import { molecularSVG, particleGroup, stoichiometryArt, alchemySeal } from './art.js';
import { ExplorationWorkbench, numberField, bindNumber, metric, makeDraggable, notice, guideStep } from './components.js';
export function mountMolecule(root,ctx){
 let selected='H2O',counts={},angle=0,tilt=.3,zoom=1,compare='CO2',preview=false;
 root.classList.add('interactive-studio','molecule-studio');
 root.innerHTML=ExplorationWorkbench(
  '<div class="studio-stage-label"><span>分子模型工作台</span><span>點選加入 · 拖曳旋轉</span></div><div class="molecule-art" tabindex="0" role="group" aria-label="分子旋轉區，拖曳或方向鍵旋轉"></div><div class="rack-heading"><b>拿取這個配方需要的原子</b><span>拿起一顆原子 · 可拖曳或點選</span></div><div class="element-rack"></div>',
  '<span class="studio-eyebrow">01 / 選擇配方</span><label class="select-label">要組哪種物質？<select class="molecule-select">'+Object.entries(molecules).map(([f,m])=>'<option value="'+f+'">'+f+' · '+m.name+'</option>').join('')+'</select></label><div class="molecule-recipe"></div><div class="atom-counts"></div><div class="molecule-readout"></div><div class="activity-status" role="status"></div><div class="button-row model-tools"><button class="secondary clear">重新組裝</button><button class="text-button complete">看完整模型</button></div><details class="view-options"><summary>調整模型視角</summary>'+numberField('molecule-zoom','模型縮放',1,.65,1.35,.05,'倍')+'<div class="button-row"><button class="secondary rotate-left" aria-label="模型向左旋轉">↶ 向左</button><button class="secondary rotate-right" aria-label="模型向右旋轉">向右 ↷</button></div><button class="text-button reset-view">還原視角</button></details>',
  '球棍模型用來看原子如何組合，大小與鍵長為教學示意。離子化合物只展示式單位的組成比例。');
 root.insertAdjacentHTML('beforeend','<div class="observation-panel"><h3>比較兩種物質的相對質量</h3><label>比較對象 <select class="molecule-compare">'+Object.entries(molecules).map(([f,m])=>'<option value="'+f+'" '+(f===compare?'selected':'')+'>'+f+' · '+m.name+'</option>').join('')+'</select></label><div class="molecule-comparison"></div><div class="comparison-definition"><b>怎麼從質量比找原子量？</b><br>待測原子的平均質量 ÷ 碳-12 原子質量＝待測元素原子量 ÷ 12。<br>例如氧：碳-12 的質量比約 4：3，氧原子量約為 12×4÷3＝16。使用同一標準時，兩元素的原子量比就是平均原子質量比。</div><details><summary>如果把比較標準加倍，原子真的變輕了嗎？</summary><div class="standard-demo"><p>原子本身沒有變重或變輕。下面只是試著換一把比較用的尺，不改課本採用的數值。</p><button class="secondary reference-toggle">把假想質量標準加倍</button><p class="reference-result">正式標準：碳-12 的相對質量是 12。</p><p>講義的另一種問法是「把碳-12 的相對數值改訂成 24」。那相當於把比較單位縮小一半，所有相對數值加倍；原子本身仍沒有變重，現行 1 mol 的粒子數也不變。</p></div></details></div>');

 prepareStudio(root,{number:'01',title:'分子組裝室',description:'選配方 → 放入原子 → 看懂相對質量。'},ctx);
 function done(){return Object.entries(parseFormula(selected)).every(([e,n])=>counts[e]===n);}
 function draw(){
  const m=molecules[selected],wanted=parseFormula(selected),missing=Object.entries(wanted).filter(([e,n])=>(counts[e]||0)<n),total=Object.values(wanted).reduce((a,b)=>a+b,0),placed=Object.values(counts).reduce((a,b)=>a+b,0),complete=done();
  root.dataset.complete=String(complete);
  root.querySelector('.molecule-recipe').innerHTML='<div><span>照著化學式組裝</span><strong>'+formulaHTML(selected)+'</strong></div><div class="assembly-count"><b>'+placed+'<small> / '+total+'</small></b><span>原子已就位</span></div><progress max="'+total+'" value="'+placed+'" aria-label="原子組裝進度"></progress>';
  root.querySelectorAll('[data-element]').forEach(b=>{const e=b.dataset.element,remaining=Math.max(0,(wanted[e]||0)-(counts[e]||0));b.disabled=!remaining;b.setAttribute('aria-label',elements[e].name+'：'+(remaining?'還要 '+remaining+' 個':'已放足'));b.dataset.needed=remaining?String(remaining):'';b.closest('.atom-supply').querySelector('.token-stock').textContent=remaining?'還需 '+remaining+' 個':'✓ 已放齊';});
  guideStep(root,complete?'組好了！把每種原子的相對質量加起來':'加入'+missing.map(([e,n])=>(n-(counts[e]||0))+' 個'+elements[e].name+'原子').join('、'),complete?'右側算式對應你剛剛放入的原子。換一個配方，再試一次。':'直接點下方原子，或把它拖進模型中的虛線位置。',complete?'.molecule-readout':'[data-element="'+missing[0][0]+'"]');
  root.querySelector('.molecule-art').innerHTML=molecularSVG(m,{angle,tilt,zoom,counts});
  root.querySelector('.atom-counts').innerHTML=Object.entries(wanted).map(([e,n])=>'<div class="atom-line '+((counts[e]||0)===n?'is-filled':'')+'"><b style="--atom:'+elements[e].color+'">'+e+'</b><span>'+elements[e].name+'<small>原子量 '+elements[e].ar+'</small></span><strong>'+(counts[e]||0)+' / '+n+'</strong><button class="remove-atom" data-remove="'+e+'" aria-label="移除一個'+elements[e].name+'原子" '+(!(counts[e]>0)?'disabled':'')+'>−</button></div>').join('');
  root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const e=b.dataset.remove;counts[e]=Math.max(0,(counts[e]||0)-1);draw();root.querySelector((counts[e]>0?'[data-remove="':'[data-element="')+e+'"]').focus({preventScroll:true});});
  const sum=Object.entries(counts).reduce((s,[e,n])=>s+n*elements[e].ar,0);
  root.querySelector('.molecule-readout').innerHTML='<span class="studio-eyebrow">'+(complete?'02 / 讀出結果':'02 / 邊組裝，邊加總')+'</span>'+metric(complete?(m.kind==='式單位'?'相對式量':'相對分子量'):'目前的相對質量總和',format(sum))+'<div class="atom-sum">'+Object.entries(wanted).map(([e])=>'<span style="--atom:'+elements[e].color+'"><i></i>'+(counts[e]||0)+' × '+elements[e].ar+'</span>').join('<b>＋</b>')+'<b>＝ '+format(sum)+'</b></div><p class="small">'+(complete?'':'尚未組好；這個加總還不是 '+selected+' 的'+(m.kind==='式單位'?'式量':'分子量')+'。')+'</p>'+(complete?'<div class="molar-handoff"><span>從一個微粒，連到一莫耳</span><b>1 mol '+formulaHTML(selected)+' → '+format(sum)+' g</b><p>莫耳質量約 '+format(sum)+' g/mol。</p></div>':'');
  root.querySelector('.molecule-comparison').innerHTML='<div class="metrics">'+metric(formulaHTML(selected),format(molecularMass(selected)))+metric(formulaHTML(compare),format(molecularMass(compare)))+metric('前者 ÷ 後者',format(molecularMass(selected)/molecularMass(compare)),'倍')+'</div><p class="small">比較一個分子／式單位的相對質量；離子晶體以式單位比較。</p>';
  notice(root,complete?'✓ 原子數正確，配方完成。':'組裝進度 '+placed+' / '+total+'。每點一次，就加入一個原子。');
  root.querySelector('.clear').textContent=preview?'換我組裝':'重新組裝';
  if(complete&&preview)notice(root,'這是完整模型示範。按「換我組裝」，親手放入原子，才會完成本站操作。');
  if(complete&&!preview&&!ctx.data.moleculeAssembled){ctx.data.moleculeAssembled=true;ctx.mark('assembled');}
 }
 function add(e){if(!ctx.predict())return;const wanted=parseFormula(selected);if(!wanted[e]||(counts[e]||0)>=wanted[e])return;counts[e]=(counts[e]||0)+1;draw();}
 function rack(){root.querySelector('.element-rack').innerHTML=Object.keys(parseFormula(selected)).map(e=>'<div class="atom-supply"><button class="element-token" data-element="'+e+'" style="--atom:'+elements[e].color+'"><b aria-hidden="true">'+e+'</b></button><span class="token-name">'+elements[e].name+'<small>原子量 '+elements[e].ar+'</small></span><span class="token-stock"></span></div>').join('');root.querySelectorAll('[data-element]').forEach(b=>makeDraggable(b,root.querySelector('.molecule-art'),()=>add(b.dataset.element),root.querySelector('.activity-status')));}
 root.querySelector('.molecule-select').onchange=e=>{selected=e.target.value;counts={};preview=false;rack();draw();};
 root.querySelector('.molecule-compare').onchange=e=>{compare=e.target.value;draw();};
 root.querySelector('.complete').onclick=()=>{if(!ctx.predict())return;preview=true;counts=parseFormula(selected);draw();};
 root.querySelector('.clear').onclick=()=>{preview=false;counts={};draw();};
 const setZoom=bindNumber(root,'molecule-zoom',v=>{zoom=v;draw();});
root.querySelector('.rotate-left').onclick=()=>{angle-=.25;draw();};root.querySelector('.rotate-right').onclick=()=>{angle+=.25;draw();};root.querySelector('.reset-view').onclick=()=>{angle=0;tilt=.3;zoom=1;setZoom(1);draw();};
const area=root.querySelector('.molecule-art');area.onselectstart=area.ondragstart=e=>e.preventDefault();let drag=null;area.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();area.focus({preventScroll:true});area.classList.add('is-rotating');drag={x:e.clientX,y:e.clientY};area.setPointerCapture(e.pointerId);};area.onpointermove=e=>{if(!drag)return;e.preventDefault();angle+=(e.clientX-drag.x)*.012;tilt+=(e.clientY-drag.y)*.01;drag={x:e.clientX,y:e.clientY};draw();};area.onpointerup=area.onpointercancel=()=>{drag=null;area.classList.remove('is-rotating');};area.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')angle-=.2;if(e.key==='ArrowRight')angle+=.2;if(e.key==='ArrowUp')tilt-=.2;if(e.key==='ArrowDown')tilt+=.2;draw();}};area.addEventListener('wheel',e=>{if(document.activeElement!==area)return;e.preventDefault();zoom=Math.max(.65,Math.min(1.35,Math.round((zoom-e.deltaY*.001)*20)/20));setZoom(zoom);draw();},{passive:false});
let doubled=false;root.querySelector('.reference-toggle').onclick=e=>{doubled=!doubled;e.target.textContent=doubled?'恢復正式標準：碳-12':'把假想質量標準加倍';root.querySelector('.reference-result').textContent=doubled?'假想比較尺變成 2 倍，碳-12 的比值會成為 6；但同一顆碳原子的真實質量完全沒變。正式相對原子質量定義仍用 1/12 碳-12。':'正式標準：碳-12 的相對質量是 12。';};

 rack();draw();return{reset(){ctx.data.moleculeAssembled=false;preview=false;counts={};angle=0;tilt=.3;zoom=1;setZoom(1);draw();}};
}
export function mountBalancer(root,ctx){
let id='water',coeff=[1,1,1],solved=new Set(ctx.data.balanced||[]);
root.classList.add('balance-studio');
root.innerHTML='<div class="equation-workbench"><div class="balance-top"><label>反應題目 <select class="balance-select">'+['water','magnesium','iron','peroxide'].map(id=>'<option value="'+id+'">'+reactions[id].name+'</option>').join('')+'</select></label><span class="balance-done"></span></div><div class="balance-alchemy"></div><div class="equation-controls" aria-label="只可修改係數"></div><details class="particle-view"><summary>看這些份數對應多少微粒</summary><div class="balance-models"></div></details><div class="balance-ledger"></div><div class="button-row"><button class="secondary balance-hint">給我一個提示</button><button class="text-button balance-reset">重新配平</button><button class="primary balance-next" disabled>下一個反應 →</button></div><div class="activity-status" role="status"></div><p class="model-note">每一框表示一個分子，或一份化學式的組成。MgO、Fe₂O₃ 的框只表示比例，不是獨立分子。右下角的小數字不能改。</p></div>';
root.insertAdjacentHTML('beforeend','<details class="balance-method"><summary>不知道從哪裡開始？看配平的三步方法</summary><p>先根據實驗確認反應物和生成物的化學式，再調整係數。配平不能證明任意想像的反應一定會發生。</p><ol><li>先選一種物質，暫定它的係數為 1。常從組成較複雜的物質開始。</li><li>以水為例：先設 H₂O 為 1，配氫得到 H₂ 為 1，再配氧得到 O₂ 為 1/2。</li><li>整式乘 2：2H₂＋O₂→2H₂O；最後檢查每種原子數，再約成最簡整數比。</li></ol><p><b>反應前後總共有幾個分子，不一定相同。</b>水的例子是 3 個反應物分子形成 2 個水分子，但 H 仍為 4 個、O 仍為 2 個。</p><p>操作器最後只填正整數係數；不能改動下標。</p></details>');
prepareStudio(root,{number:'03',title:'係數平衡',description:'先看一個完整示範，再自己調整係數、核對原子。'},ctx);
const balanceDemo=mountBalanceDemonstration(root);
function draw(){const r=reactions[id],ledger=atomLedger(r,coeff),all=[...r.left,...r.right];const matched=ledger.rows.filter(x=>x.left===x.right).length;
 root.querySelector('.balance-alchemy').innerHTML='<div class="balance-emblem">'+alchemySeal(matched+' / '+ledger.rows.length,'種元素已相等',matched/ledger.rows.length)+'</div><div><span class="studio-eyebrow">原子核對 / 即時更新</span><h3>'+(ledger.balanced?(ledger.minimal?'每種原子，都對上了。':'原子數相同，再約成最簡比。'):'讓左邊和右邊，一個都不差。')+'</h3><p>'+(ledger.balanced?all.map((f,i)=>coeff[i]+' mol '+formulaHTML(f)).join(' ： '):'每按一次 ＋，就增加一整份物質。下方會告訴你哪種原子還沒對上。')+'</p></div>';
 root.querySelector('.equation-controls').innerHTML=all.map((f,i)=>(i===r.left.length?'<strong class="equation-arrow" aria-label="反應生成">→</strong>':i?'<span class="equation-plus">＋</span>':'')+'<div class="coefficient" data-side="'+(i<r.left.length?'reactant':'product')+'"><span class="species-side">'+(i<r.left.length?'反應物':'生成物')+'</span><b>'+formulaHTML(f)+'</b><div><button data-adjust="'+i+'" data-delta="-1" aria-label="減少 '+f+' 係數" '+(coeff[i]<=1?'disabled':'')+'>−</button><output aria-label="'+f+' 係數">'+coeff[i]+'</output><button data-adjust="'+i+'" data-delta="1" aria-label="增加 '+f+' 係數" '+(coeff[i]>=12?'disabled':'')+'>＋</button></div><span class="coefficient-unit">份</span><div class="coefficient-atoms">'+Object.entries(parseFormula(f)).map(([e,n])=>'<span><i style="background:'+elements[e].color+'"></i>'+e+' <b>'+n*coeff[i]+'</b></span>').join('')+'</div></div>').join('');
 root.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>{if(!ctx.predict())return;const focusLabel=b.getAttribute('aria-label');coeff[Number(b.dataset.adjust)]+=Number(b.dataset.delta);draw();[...root.querySelectorAll('[data-adjust]')].find(x=>x.getAttribute('aria-label')===focusLabel)?.focus();});root.querySelector('.balance-models').innerHTML=all.map((f,i)=>'<div class="particle-species"><small class="species-side">'+(i<r.left.length?'反應物':'生成物')+'</small><strong>'+coeff[i]+formulaHTML(f)+'</strong>'+particleGroup(f,coeff[i])+'</div>').join('');root.querySelector('.balance-ledger').innerHTML='<div class="ledger-title"><b>每種原子，一起核對</b><span>反應前 → 反應後</span></div>'+ledger.rows.map(x=>{const equal=x.left===x.right,max=Math.max(x.left,x.right,1);return '<div class="ledger-row '+(equal?'is-equal':'is-mismatch')+'"><span class="ledger-element" style="--atom:'+elements[x.e].color+'">'+x.e+'</span><div class="ledger-count"><span>左邊 <b>'+x.left+'</b></span><i style="--fill:'+x.left/max*100+'%"></i></div><div class="ledger-count"><span>右邊 <b>'+x.right+'</b></span><i style="--fill:'+x.right/max*100+'%"></i></div><strong class="ledger-verdict">'+(equal?'✓ 相等':(x.left>x.right?'右邊少 ':'左邊少 ')+Math.abs(x.left-x.right))+'</strong></div>';}).join('');
root.querySelector('.balance-next').disabled=!(ledger.balanced&&ledger.minimal);root.querySelector('.balance-next').hidden=solved.size===4;
if(ledger.balanced&&ledger.minimal){const first=!solved.has(id);solved.add(id);ctx.data.balanced=[...solved];ctx.save();notice(root,'平衡成功！每種元素的原子數相同，而且是最簡整數比。');if(first)ctx.mark('balanced-reaction');root.querySelector('.balance-next').hidden=solved.size===4;}
else if(ledger.balanced)notice(root,'原子數對上了！再把係數一起除以相同的數，約成最簡整數比。');
else notice(root,ledger.rows.filter(x=>x.left!==x.right).map(x=>x.e+'：左 '+x.left+'、右 '+x.right).join('；')+'。調整整組物質的係數。');
guideStep(root,ledger.balanced?(ledger.minimal?'配平成功！下一步看莫耳數比':'原子數對上了，再把係數約小'):'先找左右數量不同的原子',ledger.balanced?'係數代表莫耳數的比例。換另一題再練習，不能把下標改掉。':'琥珀色的核對列會顯示哪一邊還少幾個。用 ＋／− 增減整份物質。',ledger.balanced?'.balance-select':'.equation-controls');root.querySelector('.balance-done').textContent='已完成 '+solved.size+' / 4 題';root.querySelector('.equation-workbench').classList.toggle('balanced',ledger.balanced&&ledger.minimal);}
root.querySelector('.balance-next').onclick=()=>{const ids=['water','magnesium','iron','peroxide'];id=ids[(ids.indexOf(id)+1)%ids.length];coeff=reactions[id].coeff.map(()=>1);root.querySelector('.balance-select').value=id;draw();};
root.querySelector('.balance-select').onchange=e=>{id=e.target.value;coeff=reactions[id].coeff.map(()=>1);draw();};root.querySelector('.balance-reset').onclick=()=>{coeff=coeff.map(()=>1);draw();};root.querySelector('.balance-hint').onclick=()=>{notice(root,{water:'右邊先放 2 份 H₂O，氧就和 1 份 O₂ 相等，再調整 H₂。',magnesium:'O₂ 有 2 個氧，先讓右側出現 2 份 MgO。',iron:'氧的最小公倍數是 6：試試 3O₂ 和 2Fe₂O₃，再配鐵。',peroxide:'先讓 H₂O₂ 與 H₂O 係數同為 2，剩下的氧組成 O₂。'}[id]);};
draw();return{reset(){balanceDemo.reset();solved.clear();ctx.data.balanced=[];coeff=coeff.map(()=>1);draw();}};
}
export function mountStoich(root,ctx){
 root.classList.add('stoich-studio');
 let id='peroxide',unit='g',value=34,productIndex=1,current=null;
 let level=1,levels=new Set(ctx.data.stoichLevels||[]),levelDrafts=new Map();
 const units={g:'公克 g',mg:'毫克 mg',kg:'公斤 kg',mol:'莫耳 mol',particles:'粒子個數'};
 const names={H2O2:'過氧化氫',H2O:'水',O2:'氧氣',Mg:'鎂',MgO:'氧化鎂',CaCO3:'碳酸鈣',CaCl2:'氯化鈣',CO2:'二氧化碳'};
 root.innerHTML=ExplorationWorkbench('<div class="stoich-visual"></div>','<div class="stoich-stage-controls"></div>','教學模型：假設反應完全進行、沒有材料損失；其他反應物給得足夠。')+'<details class="workshop-challenges" open><summary>換你練習：三個小關卡</summary><div class="challenge-inner"><div class="level-tabs" role="group" aria-label="工坊三關">'+[1,2,3].map(n=>'<button data-level="'+n+'"></button>').join('')+'</div><div class="level-question"></div><div class="answer-row"><label>我的答案<input class="level-answer" type="number" step="any" min="0"></label><span class="level-unit"></span><button class="primary level-check">檢查本關</button></div><p class="level-feedback" role="status"></p><button type="button" class="secondary level-next" hidden>繼續下一關 →</button><details class="final-challenge"><summary>挑戰：里昂需要 8 g 氧氣</summary><p>有 40 g 過氧化氫水溶液，其中一半質量是 H₂O₂，另一半是水。完全分解後，能收集到 8 g 氧氣嗎？先算裡面有幾克 H₂O₂。</p><div class="answer-row"><label>算出的氧氣質量<input class="challenge-answer" type="number" step="any" min="0"></label><span>g</span><button class="secondary challenge-check">檢查挑戰</button></div><p class="challenge-feedback" role="status"></p></details></div></details>';
 prepareStudio(root,{number:'04',title:'產量計算工作室',description:'先跟著例題看懂比例，再調整用量，最後自己練習。'},ctx);

 const exampleReaction=reactions.peroxide, exampleMass=exampleReaction.coeff[0]*molecularMass('H2O2'),exampleOxygen=react('peroxide',[exampleMass]).products[1].mass,exampleWater=react('peroxide',[exampleMass]).products[0].mass;
 const example=document.createElement('section');example.className='worked-example';example.setAttribute('aria-label','先看一個完整例題');
 example.innerHTML='<div class="example-heading"><span class="studio-eyebrow">先看示範 / 不用填答案</span><h3>68 g 過氧化氫，能產生多少氧氣？</h3><p>先假設完全分解。這裡的 68 g 是純 H₂O₂，不是過氧化氫水溶液的總重。</p></div><div class="example-tabs" role="group" aria-label="例題示範步驟"><button data-example-step="0">1 看配方</button><button data-example-step="1">2 換成克數</button><button data-example-step="2">3 用量減半</button></div><div class="example-board" aria-live="polite"></div><div class="example-actions"><button class="primary example-next">下一步：換成克數 →</button><button class="text-button example-explore">我懂了，調整用量 ↓</button></div>';
 const free=document.createElement('details');free.className='free-stoich';free.innerHTML='<summary><span>接著試試：改用量，看答案怎麼變</span><small>系統自動計算，不用作答</small></summary>';const bench=root.querySelector('.workbench');bench.before(example,free);free.append(bench);
 let exampleStep=0;
 const exampleViews=[
 '<span class="example-caption">把反應式當作一張「份數配方」</span><div class="example-recipe"><div><b>2 <small>mol</small></b><strong>H₂O₂</strong><span>過氧化氫</span></div><i>→</i><div><b>2 <small>mol</small></b><strong>H₂O</strong><span>水</span></div><i>＋</i><div><b>1 <small>mol</small></b><strong>O₂</strong><span>氧氣</span></div></div><p class="example-takeaway">每 <b>2 mol 過氧化氫</b>，會生成 <b>1 mol 氧氣</b>。先看懂係數比 2：1，還不用算克數。</p>',
 '<span class="example-caption">每莫耳幾克 × 有幾莫耳 ＝ 總共幾克</span><div class="example-recipe"><div><span>2 × 34 g</span><b>'+exampleMass+' <small>g</small></b><strong>H₂O₂</strong></div><i>→</i><div><span>2 × 18 g</span><b>'+exampleWater+' <small>g</small></b><strong>H₂O</strong></div><i>＋</i><div><span>1 × 32 g</span><b>'+exampleOxygen+' <small>g</small></b><strong>O₂</strong></div></div><p class="example-takeaway">所以 <b>'+exampleMass+' g 過氧化氫 → '+exampleOxygen+' g 氧氣</b>，同時生成 '+exampleWater+' g 水。檢查一下：'+exampleWater+'＋'+exampleOxygen+'＝'+exampleMass+' g。</p>',
 '<span class="example-caption">同一個反應，材料減半，產物也減半</span><div class="example-halves"><div><span>原本</span><b>'+exampleMass+' g H₂O₂ → '+exampleOxygen+' g O₂</b></div><span class="half-arrow">兩邊都 ÷ 2 ↓</span><div><span>減半</span><b>'+exampleMass/2+' g H₂O₂ → '+exampleOxygen/2+' g O₂</b></div></div><p class="example-takeaway">不用重新背算式。抓住 <b>68：32</b> 的質量比，就能預測其他用量的氧氣產量。</p>'
 ];
 function showExample(){root.querySelector('.example-board').innerHTML=exampleViews[exampleStep];root.querySelectorAll('[data-example-step]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.exampleStep===exampleStep)));root.querySelector('.example-next').textContent=['下一步：換成克數 →','下一步：用量減半 →','看懂了，試著改用量 →'][exampleStep];}
 const openFree=()=>{free.open=true;free.scrollIntoView({behavior:'auto',block:'start'});root.querySelector('.stoich-value').focus({preventScroll:true});};
 root.querySelectorAll('[data-example-step]').forEach(b=>b.onclick=()=>{exampleStep=+b.dataset.exampleStep;showExample();});root.querySelector('.example-next').onclick=()=>{if(exampleStep<2){exampleStep++;showExample();}else openFree();};root.querySelector('.example-explore').onclick=openFree;showExample();
 const control=root.querySelector('.stoich-stage-controls');
 function inUnit(grams){const c=convert(grams,'g',reactions[id].left[0]);return unit==='mol'?c.mol:unit==='particles'?Math.round(c.particles):c.mass/{g:1,mg:.001,kg:1000}[unit];}
 function compute(raw){try{if(raw===''||!Number.isFinite(Number(raw))||Number(raw)<0)throw new Error('請填入 0 或大於 0 的數字。');if(Number(raw)>1e30)throw new Error('數字太大了，請把材料用量調小。');finite(raw,0,1e30);if(unit==='particles'&&!Number.isInteger(Number(raw)))throw new Error('粒子要一個一個數，請輸入整數。');const r=reactions[id],f=r.left[0],c=convert(Number(raw),unit,f);if(c.mass>1e6)throw new Error('材料最多可輸入 1,000,000 g，請把數字調小。');const masses=r.left.map((formula,i)=>i===0?c.mass:c.mol/r.coeff[0]*r.coeff[i]*molecularMass(formula)*2+1),out=react(id,masses);value=Number(raw);current={r,f,c,out,product:out.products[productIndex]};return '';}catch(e){current=null;return e.message;}}
 function steps(){const {r,c,product}=current,a=r.coeff[0],b=r.coeff[r.left.length+productIndex],M=molecularMass(product.formula);return[
  {title:'材料有幾莫耳？',why:'每 '+c.M+' g 是 1 mol，所以用克數除以 '+c.M+'。',formula:format(c.mass)+' g ÷ '+c.M+' g/mol',answer:c.mol,unit:'mol',hint:'算 '+format(c.mass)+' ÷ '+c.M+'，就知道材料有幾莫耳。'},
  {title:'會有幾莫耳產物？',why:'配方是 '+a+' mol '+names[current.f]+' → '+b+' mol '+names[product.formula]+'，所以乘 '+b+'/'+a+'。',formula:format(c.mol)+' mol × '+b+'/'+a,answer:product.mol,unit:'mol',hint:'用剛才的 '+format(c.mol)+' mol，乘上「產物係數 '+b+' ÷ 反應物係數 '+a+'」。'},
  {title:'產物有幾克？',why:'1 mol '+names[product.formula]+' 是 '+M+' g，所以再乘 '+M+'。',formula:format(product.mol)+' mol × '+M+' g/mol',answer:product.mass,unit:'g',hint:'用 '+format(product.mol)+' × '+M+'，把產物的莫耳數換回克數。'}
 ];}

 function drawVisual(){
  const area=root.querySelector('.stoich-visual');area.dataset.phase='auto';
  if(!current){area.innerHTML='<div class="invalid-state"><h3>先把用量改好</h3><p>請依用量欄位的提示，修正輸入的數字。</p></div>';return;}
  const {f,c,out,product}=current;
  area.innerHTML='<div class="stoich-flow"><div><span>投入材料</span><b>'+format(c.mass)+' <small>g</small></b><strong>'+formulaHTML(f)+'</strong></div><span class="flow-arrow" aria-hidden="true">→</span><div><span>指定產物</span><b>'+format(product.mass)+' <small>g</small></b><strong>'+formulaHTML(product.formula)+'</strong></div></div><section class="stoich-result-card"><span class="eyebrow">自動算給你看</span><h3>'+format(c.mass)+' g '+formulaHTML(f)+' 可以生成</h3><div class="stoich-result-number" data-result="product-mass">'+format(product.mass)+' <small>g '+formulaHTML(product.formula)+'</small></div><p>以下三步由系統自動計算。看懂後，再到下方題目自己練習。</p><div class="equation">'+equationHTML(id)+'</div><ol class="automatic-steps">'+steps().map((s,i)=>'<li><span class="automatic-step-number">'+(i+1)+'</span><div><b>'+s.title+'</b><p>'+s.why+'</p><div class="automatic-formula">'+s.formula+' ＝ <strong>'+format(s.answer)+' '+s.unit+'</strong></div></div></li>').join('')+'</ol><details class="apparatus-details"><summary>查看材料與產物的示意</summary><div class="stoich-apparatus">'+stoichiometryArt(f,c.mass,out.products,{revealed:true})+'</div></details><p class="auto-rounding-note">畫面數值取近似值；計算時保留完整精度。</p><details class="result-particles"><summary>這份材料有多少個粒子？</summary><p>'+format(c.mass)+' g '+formulaHTML(f)+'＝'+format(c.mol)+' mol，約有 '+format(c.particles)+' 個'+(f==='Mg'?'鎂原子':f==='CaCO3'?'碳酸鈣式單位':'過氧化氫分子')+'。</p></details></section>';
 }
 function syncDose(raw){
  const error=compute(raw),input=control.querySelector('.stoich-value'),range=control.querySelector('.stoich-dose-slider');input.setCustomValidity(error);control.querySelector('.stoich-error').textContent=error;
  if(current){input.value=String(value);range.max=String(inUnit(Math.max(100,current.c.mass)));range.value=String(value);guideStep(root,'用量一改，答案立即更新','上方自動示範三步計算；下方的小關卡才需要自己作答。','.stoich-value');}
  else guideStep(root,'這個用量需要調整',error,'.stoich-value');input.setAttribute('aria-invalid',String(!!error));control.querySelectorAll('[data-dose]').forEach(b=>b.setAttribute('aria-pressed',String(!!current&&Math.abs(current.c.mass-Number(b.dataset.dose))<1e-8)));drawVisual();
 }
 function show(){
  const r=reactions[id];
  control.innerHTML='<span class="panel-eyebrow">自由調整用量</span><h3>讓系統算給你看</h3><label class="select-label">做哪個反應？<select class="stoich-reaction">'+['peroxide','magnesium','limestone'].map(x=>'<option value="'+x+'" '+(x===id?'selected':'')+'>'+reactions[x].name+'</option>').join('')+'</select></label><label class="select-label">想算哪個產物？<select class="stoich-product">'+r.right.map((f,i)=>'<option value="'+i+'" '+(i===productIndex?'selected':'')+'>'+names[f]+'（'+f+'）</option>').join('')+'</select></label><label class="select-label dose-label">'+names[r.left[0]]+'的用量（'+units[unit]+'）<input class="stoich-value" type="number" min="0" max="1e30" step="any" value="'+value+'"></label><input class="stoich-dose-slider" aria-label="材料用量滑桿" type="range" min="0" max="'+inUnit(Math.max(100,current?.c.mass||0))+'" step="any" value="'+value+'"><div class="dose-presets">'+({peroxide:[17,34,68],magnesium:[6,12,24],limestone:[5,10,20]}[id]).map(v=>'<button data-dose="'+v+'">'+v+' g</button>').join('')+'</div><div class="dose-scale"><span>比較用量</span><button type="button" data-scale="0.5">減半 ÷ 2</button><button type="button" data-scale="2">加倍 × 2</button></div><p class="stoich-error field-error" role="status"></p><p class="excess-note">'+(r.left.length>1?'另一種材料給得夠多，不會先用完（足量）。':'這裡只算 H₂O₂ 的量，不包含溶液裡的水。')+'</p><details class="input-unit-options"><summary>想換別的單位輸入？</summary><label class="select-label">單位<select class="stoich-unit">'+Object.entries(units).map(([u,t])=>'<option value="'+u+'" '+(u===unit?'selected':'')+'>'+t+'</option>').join('')+'</select></label><p>換單位不會改變材料多少。例如 1 g＝1,000 mg。</p></details><button class="secondary auto-practice-jump">換我自己練習 ↓</button><button class="text-button stoich-reset">恢復 34 g 過氧化氫</button>';
  control.querySelector('.stoich-value').oninput=e=>syncDose(e.target.value);
  control.querySelector('.stoich-dose-slider').oninput=e=>syncDose(unit==='particles'?Math.round(Number(e.target.value)):Number(Number(e.target.value).toPrecision(4)));
  control.querySelectorAll('[data-scale]').forEach(b=>b.onclick=()=>{if(current)syncDose(unit==='particles'?Math.floor(value*Number(b.dataset.scale)):Number((value*Number(b.dataset.scale)).toPrecision(12)));});
  control.querySelectorAll('[data-dose]').forEach(b=>b.onclick=()=>syncDose(inUnit(Number(b.dataset.dose))));
  control.querySelector('.stoich-reaction').onchange=e=>{id=e.target.value;productIndex=reactions[id].right.length-1;compute(value);show();};
  control.querySelector('.stoich-product').onchange=e=>{productIndex=Number(e.target.value);compute(value);show();};
  control.querySelector('.stoich-unit').onchange=e=>{const grams=current?.c.mass??34;unit=e.target.value;value=inUnit(grams);compute(value);show();control.querySelector('.input-unit-options').open=true;};
  control.querySelector('.stoich-reset').onclick=reset;
  control.querySelector('.auto-practice-jump').onclick=()=>{const panel=root.querySelector('.workshop-challenges');panel.open=true;panel.scrollIntoView({behavior:'auto',block:'start'});panel.querySelector('.level-answer').focus({preventScroll:true});};
  syncDose(value);
 }
 const tasks={1:{q:'18 g 水，每 1 mol 是 18 g。這些水有幾 mol？',unit:'mol',a:1,reason:'18÷18＝1 mol。'},2:{q:'0.5 mol 水約有幾個水分子？很大的數可寫成 3.01e23。',unit:'個分子',a:3.01e23,reason:'0.5×6.02×10²³＝3.01×10²³ 個水分子。'},3:{q:'8.4 g 小蘇打和夠多的醋酸反應，產生幾克 CO₂？1 mol 小蘇打是 84 g，可生成 1 mol、44 g 的 CO₂。',unit:'g',a:4.4,reason:'8.4÷84＝0.1 mol；0.1×1×44＝4.4 g CO₂。'}};
 function showLevel(){const t=tasks[level];root.querySelector('.level-question').innerHTML='<h3>第 '+level+' 關</h3><p>'+t.q+'</p>';root.querySelector('.level-unit').textContent=t.unit;root.querySelector('.level-answer').value=levelDrafts.get(level)||'';root.querySelector('.level-answer').removeAttribute('aria-invalid');root.querySelector('.level-next').hidden=true;root.querySelector('.level-feedback').textContent='';root.querySelector('.level-feedback').className='level-feedback';root.querySelectorAll('[data-level]').forEach(b=>{const n=Number(b.dataset.level);b.setAttribute('aria-pressed',String(n===level));b.textContent=['1 · 克與莫耳','2 · 莫耳與粒子','3 · 算產物'][n-1]+(levels.has(n)?' ✓':'');});}
 root.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=Number(b.dataset.level);showLevel();});
 root.querySelector('.level-answer').addEventListener('input',e=>{levelDrafts.set(level,e.target.value);root.querySelector('.level-feedback').textContent='';root.querySelector('.level-feedback').className='level-feedback';root.querySelector('.level-next').hidden=true;e.target.removeAttribute('aria-invalid');});
 root.querySelector('.level-answer').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();root.querySelector('.level-check').click();}});
 root.querySelector('.level-next').onclick=()=>{if(level<3){level++;showLevel();root.querySelector('.level-answer').focus({preventScroll:true});}};
 root.querySelector('.challenge-answer').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();root.querySelector('.challenge-check').click();}});
 root.querySelector('.level-check').onclick=()=>{if(!ctx.predict())return;const raw=root.querySelector('.level-answer').value,n=Number(raw),t=tasks[level];if(raw===''||!Number.isFinite(n)||n<0){root.querySelector('.level-feedback').textContent='請輸入 0 或大於 0 的數字。';root.querySelector('.level-answer').setAttribute('aria-invalid','true');root.querySelector('.level-answer').focus({preventScroll:true});return;}const ok=Math.abs(n-t.a)<=Math.max(t.a*.005,1e-8);if(ok){levels.add(level);ctx.data.stoichLevels=[...levels];ctx.save();root.querySelector('[data-level="'+level+'"]').textContent=['1 · 克與莫耳','2 · 莫耳與粒子','3 · 算產物'][level-1]+' ✓';ctx.mark('workshop-level');}root.querySelector('.level-next').hidden=!ok||level===3;root.querySelector('.level-answer').setAttribute('aria-invalid',String(!ok));root.querySelector('.level-feedback').className='level-feedback '+(ok?'correct':'incorrect');root.querySelector('.level-feedback').innerHTML=ok?'✓ 正確！'+t.reason:'<b>再試一次：</b>'+({1:'題目問幾莫耳，用總質量除以每莫耳的質量。',2:'一莫耳有 6.02 × 10²³ 個，半莫耳呢？可用 e23 輸入 ×10²³。',3:'先算小蘇打的莫耳數，再用 1：1 的比例算 CO₂，最後乘上 44 g/mol。'}[level])+'<details class="solution-reveal"><summary>看完整計算</summary><p>'+t.reason+'</p></details>';};
 root.querySelector('.challenge-check').onclick=()=>{const raw=root.querySelector('.challenge-answer').value,answer=react('peroxide',[20]).products[1].mass,ok=raw!==''&&Number.isFinite(Number(raw))&&Math.abs(Number(raw)-answer)<.05;root.querySelector('.challenge-feedback').textContent=(ok?'✓ 正確，氧氣夠用！':'算出的氧氣約 9.41 g，所以夠用。')+'先算 H₂O₂：40×50%＝20 g。再算氧氣：20÷34×(1/2)×32≈9.41 g。原來的 20 g 水，加上新生成的約 10.59 g 水，再加氧氣，總共仍是 40 g。';};

 function reset(){id='peroxide';unit='g';value=34;productIndex=1;compute(value);show();}
 compute(value);show();showLevel();return{reset(){exampleStep=0;showExample();free.open=false;levels.clear();levelDrafts.clear();ctx.data.stoichLevels=[];level=1;reset();showLevel();root.querySelector('.challenge-answer').value='';root.querySelector('.challenge-feedback').textContent='';}};
}
